int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf) {
    struct smb_hdr *smb;
    struct smb_echo_req *req;
    struct smb_echo_rsp *rsp;
    int rc = 0;
    int bytes_read;
    void *iov[1];

    if (!tcon || !psrch_inf)
        return -EINVAL;

    smb = cifs_smb_init(SMB_COM_SEARCH, 0, tcon, NULL, 0);
    if (!smb)
        return -ENOMEM;

    req = (struct smb_echo_req *)((char *)smb + 4);
    req->search_handle = cpu_to_le16(searchHandle);
    req->search_info = psrch_inf;

    iov[0] = smb;
    rc = SendReceive2(xid, tcon->ses, iov, 1, &bytes_read, 0);
    if (rc)
        goto out;

    rsp = (struct smb_echo_rsp *)((char *)smb + 4);
    if (rsp->end_of_search)
        psrch_inf->end_of_search = true;

    if (rsp->num_entries > 0) {
        memcpy(psrch_inf->entries, rsp->entries, rsp->num_entries * sizeof(struct cifs_search_entry));
        psrch_inf->num_entries = rsp->num_entries;
    } else {
        psrch_inf->num_entries = 0;
    }

out:
    kfree(smb);
    return rc;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf) {
    int rc = 0;
    struct smb_hdr *smb;
    struct smb2_search_info *srch_rsp = NULL;
    unsigned int resp_buftype = 0;
    void *resp_buf = NULL;

    if (!tcon || !psrch_inf) {
        return -EINVAL;
    }

    smb = cifs_compose_smb2_request(xid, tcon, SMB2_SEARCH_NEXT, sizeof(struct smb2_search_next_req), NULL);
    if (!smb) {
        return -ENOMEM;
    }

    rc = SendReceive(xid, tcon, (struct smb_tcon *)smb, &resp_buf, &resp_buftype, 0);
    if (rc) {
        cifs_buf_release(smb);
        return rc;
    }

    if (resp_buftype == CIFS_SMALL_BUF_TYPE) {
        srch_rsp = (struct smb2_search_info *)resp_buf;
    } else if (resp_buftype == CIFS_LARGE_BUF_TYPE) {
        srch_rsp = (struct smb2_search_info *)resp_buf;
    }

    if (!srch_rsp) {
        cifs_buf_release(smb);
        cifs_free_buftype(resp_buftype, resp_buf);
        return -EIO;
    }

    psrch_inf->searchHandle = srch_rsp->searchHandle;
    psrch_inf->endOfSearch = le16_to_cpu(srch_rsp->endOfSearch);

    if (psrch_inf->endOfSearch)
        psrch_inf->flags |= CIFS_SEARCH_END;

    cifs_buf_release(smb);
    cifs_free_buftype(resp_buftype, resp_buf);

    return 0;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf) {
    int rc = 0;
    struct smb2_search_request *req;
    struct smb2_search_response *resp;
    struct kvec iov[1];
    struct kvec resp_iov[1];
    int resp_len;

    req = cifs_smb2_init(SMB2_SEARCH, tcon, NULL, 0, 0, NULL);
    if (!req) {
        return -ENOMEM;
    }

    req->SearchHandle = searchHandle;
    req->SearchFlags = psrch_inf->SearchFlags;
    req->FileInformationClass = psrch_inf->FileInformationClass;
    req->SearchPatternLength = psrch_inf->SearchPatternLength;
    if (psrch_inf->SearchPatternLength > 0) {
        iov[0].iov_base = psrch_inf->SearchPattern;
        iov[0].iov_len = psrch_inf->SearchPatternLength;
        rc = cifs_smb2_ioctl(xid, tcon, req, iov, 1, NULL, NULL);
        if (rc < 0) {
            goto out;
        }
    }

    resp_len = 0;
    rc = cifs_smb2_call(xid, tcon, (struct smb2_hdr *)req, iov, 1,
                        (struct smb2_hdr **)&resp, resp_iov, 1, &resp_len);
    if (rc < 0) {
        goto out;
    }

    psrch_inf->SearchHandle = resp->SearchHandle;
    psrch_inf->SearchNext = resp->SearchNext;
    psrch_inf->EndOfSearch = resp->EndOfSearch;
    psrch_inf->SearchCount = resp->SearchCount;

    if (resp->EndOfSearch)
        psrch_inf->EndOfSearch = true;

out:
    cifs_smb2_free(req);
    return rc;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf) {
    struct smb_hdr *smb;
    struct smb_composite *composite;
    int rc = 0;
    int byte_count;

    composite = cifs_smb_composite_init(xid, tcon, 0);
    if (composite == NULL)
        return -ENOMEM;

    smb = &composite->smb;

    smb->command = SMB_COM_SEARCH;
    smb->word_count = 12;
    put_unaligned_le16(searchHandle, &smb->data[0]);
    put_unaligned_le16(psrch_inf->max_entries, &smb->data[2]);
    put_unaligned_le16(psrch_inf->search_resume_key, &smb->data[4]);
    put_unaligned_le32(psrch_inf->last_search_id, &smb->data[6]);
    put_unaligned_le16(psrch_inf->flags, &smb->data[10]);

    byte_count = 12 * 2;
    smb->byte_count = cpu_to_le16(byte_count);

    rc = SendReceive(xid, tcon, composite, 0);
    if (rc != 0)
        goto out;

    if (composite->smb.data != NULL && composite->smb.byte_count > 0) {
        psrch_inf->search_resume_key = get_unaligned_le16(composite->smb.data);
        psrch_inf->last_search_id = get_unaligned_le32(composite->smb.data + 2);
        psrch_inf->num_entries = get_unaligned_le16(composite->smb.data + 6);
    }

    if (psrch_inf->num_entries == 0)
        psrch_inf->end_of_search = true;

out:
    cifs_smb_composite_free(composite);
    return rc;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf)
{
    int rc = 0;
    struct smb2_search_request *sr = NULL;
    struct smb2_search_response *srp = NULL;
    struct kvec iov[1];
    int resp_buftype;
    int bytes_returned;

    sr = cifs_buf_get();
    if (!sr) {
        rc = -ENOMEM;
        goto out;
    }

    iov[0].iov_base = sr;
    iov[0].iov_len = get_req_size(sr);

    rc = SMB2_ioctl(xid, tcon, searchHandle, FSCTL_SRV_ENUMERATE, iov, 1, NULL, 0);
    if (rc < 0)
        goto out;

    rc = SMB2_query_info(xid, tcon, searchHandle, 0, 0, 0, NULL, 0);
    if (rc < 0)
        goto out;

    srp = (struct smb2_search_response *)sr;
    bytes_returned = le32_to_cpu(srp->OutputBufferLength);

    if (bytes_returned > 0) {
        psrch_inf->unicode = true;
        psrch_inf->eof = false;
        psrch_inf->ntwrk_buf = (char *)srp + sizeof(struct smb2_search_response);
        psrch_inf->ntwrk_buf_size = bytes_returned;
    } else {
        psrch_inf->eof = true;
    }

out:
    if (sr)
        free_rsp_buf(resp_buftype, sr);
    return rc;
}
